functions.source:
async (allowedAttempts) => {
        const identifier = `2fa-attempts-${signedTwoFactorCookie}`, consumed = await ctx.context.internalAdapter.consumeVerificationValue(identifier).catch(() => null);
        if (!consumed)
          throw APIError.from("UNAUTHORIZED", TWO_FACTOR_ERROR_CODES.INVALID_TWO_FACTOR_COOKIE);
        const parsed = Number(consumed.value), attempts = Number.isInteger(parsed) && parsed >= 0 ? parsed : allowedAttempts;
        if (attempts >= allowedAttempts) {
          try {
            await ctx.context.internalAdapter.consumeVerificationValue(signedTwoFactorCookie);
          } catch {
            expireCookie(ctx, twoFactorCookie);
            throw APIError.from("INTERNAL_SERVER_ERROR", {
              message: "Failed to invalidate two-factor challenge",
              code: "FAILED_TO_INVALIDATE_TWO_FACTOR_CHALLENGE"
            });
          }
          expireCookie(ctx, twoFactorCookie);
          throw APIError.from("BAD_REQUEST", TWO_FACTOR_ERROR_CODES.TOO_MANY_ATTEMPTS_REQUEST_NEW_CODE);
        }
        const rearm = (count) => ctx.context.internalAdapter.createVerificationValue({
          value: `${count}`,
          identifier,
          expiresAt: verificationToken.expiresAt
        }).catch(() => {});
        return {
          recordFailure: () => rearm(attempts + 1),
          restore: () => rearm(attempts)
        };
      }

